func (q *Queries) ListNumberRules(ctx context.Context, tenantID int64) ([]NumberRule, error) {
	rows, err := q.db.Query(ctx, listNumberRules, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []NumberRule
	for rows.Next() {
		var i NumberRule
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.BizType,
			&i.Prefix,
			&i.Period,
			&i.SeqLen,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

